import React, { useMemo, useState, useEffect } from 'react';
import DevNoticeModal from './DevNoticeModal';
import { useDevNotice } from './DevNoticeContext';
import {
  ResponsiveContainer,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  Brush,
  ReferenceLine,
  Area,
  AreaChart,
  ComposedChart
} from 'recharts';

// Fungsi helper untuk memformat tanggal
const formatDate = (dateString) => {
  const date = new Date(dateString);
  // Cek apakah tanggal valid
  if (isNaN(date.getTime())) return dateString;

  return date.toLocaleDateString('id-ID', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
  });
};

// Fungsi helper untuk memformat angka sebagai mata uang
const formatCurrency = (value, currencySymbol = 'Rp') => {
  if (typeof value !== 'number') return '-';
  return `${currencySymbol} ${value.toLocaleString('id-ID')}`;
};

// Custom Tooltip komponen
const CustomTooltip = ({ active, payload, label, currencySymbol }) => {
  if (!active || !payload || !payload.length) return null;

  const data = payload[0].payload;

  // Hitung perubahan harga dari titik sebelumnya jika tersedia
  const priceChange = data.previousClose ? data.Close - data.previousClose : 0;
  const percentChange = data.previousClose ? (priceChange / data.previousClose) * 100 : 0;
  const isPositive = priceChange >= 0;

  return (
      <div className="custom-tooltip" style={{
        backgroundColor: 'white',
        padding: '15px',
        border: `1px solid ${isPositive ? 'rgba(76, 175, 80, 0.3)' : 'rgba(229, 57, 53, 0.3)'}`,
        borderRadius: '8px',
        boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
        minWidth: '250px',
        transition: 'none' // Hilangkan transition
      }}>
        <p style={{
          fontWeight: 'bold',
          marginBottom: '8px',
          borderBottom: '1px solid #eee',
          paddingBottom: '8px',
          fontSize: '16px',
          color: isPositive ? '#2E7D32' : '#C62828'
        }}>
          {formatDate(data.Date || data.Datetime)}
        </p>
        <div style={{ fontSize: '14px' }}>
          <p style={{ margin: '5px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Buka:</span>
            <span style={{ fontWeight: '600' }}>{formatCurrency(data.Open, currencySymbol)}</span>
          </p>
          <p style={{ margin: '5px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Tertinggi:</span>
            <span style={{ fontWeight: '600' }}>{formatCurrency(data.High, currencySymbol)}</span>
          </p>
          <p style={{ margin: '5px 0', display: 'flex', justifyContent: 'space-between' }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Terendah:</span>
            <span style={{ fontWeight: '600' }}>{formatCurrency(data.Low, currencySymbol)}</span>
          </p>
          <p style={{
            margin: '5px 0',
            display: 'flex',
            justifyContent: 'space-between',
            backgroundColor: isPositive ? 'rgba(76, 175, 80, 0.1)' : 'rgba(229, 57, 53, 0.1)',
            padding: '5px 8px',
            borderRadius: '4px'
          }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Tutup:</span>
            <span style={{ fontWeight: 'bold', fontSize: '16px', color: isPositive ? '#2E7D32' : '#C62828' }}>
            {formatCurrency(data.Close, currencySymbol)}
          </span>
          </p>
          {data.previousClose && (
              <p style={{ margin: '5px 0', display: 'flex', justifyContent: 'space-between' }}>
                <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Perubahan:</span>
                <span style={{ fontWeight: '600', color: isPositive ? '#2E7D32' : '#C62828' }}>
              {isPositive ? '+' : ''}{formatCurrency(priceChange, currencySymbol)} ({isPositive ? '+' : ''}{percentChange.toFixed(2)}%)
            </span>
              </p>
          )}
          <p style={{
            margin: '5px 0',
            display: 'flex',
            justifyContent: 'space-between',
            borderTop: '1px solid #eee',
            paddingTop: '8px',
            marginTop: '8px'
          }}>
            <span style={{ marginRight: '15px', color: '#666', fontWeight: '500' }}>Volume:</span>
            <span style={{ fontWeight: '600' }}>{typeof data.Volume === 'number' ? data.Volume.toLocaleString('id-ID') : '-'}</span>
          </p>
        </div>
      </div>
  );
};

const StockChart = ({ data, currencySymbol = 'Rp', chartType = 'composed' }) => {
  // Use the DevNotice context
  const { showDevNotice, handleCloseDevNotice } = useDevNotice();

  // State untuk menyimpan ukuran layar
  const [isMobileView, setIsMobileView] = useState(false);

  // Effect untuk mendeteksi ukuran layar
  useEffect(() => {
    const checkIsMobile = () => {
      setIsMobileView(window.innerWidth < 768);
    };

    // Cek ketika komponen dimount
    checkIsMobile();

    // Set event listener untuk resize
    window.addEventListener('resize', checkIsMobile);

    // Cleanup event listener
    return () => window.removeEventListener('resize', checkIsMobile);
  }, []);

  // Persiapkan data untuk chart melalui useMemo untuk optimasi
  const {
    chartData,
    firstPrice,
    lastPrice,
    overallChange,
    overallPercentChange,
    isPositiveOverall,
    lastDate,
    yAxisDomain,
    shouldShowAllTicks,
    isEmpty
  } = useMemo(() => {
    // Pastikan data tidak kosong
    if (!data || data.length === 0) {
      return { isEmpty: true };
    }

    // Urutkan berdasarkan tanggal
    const sortedData = [...data].sort((a, b) => {
      const dateA = new Date(a.Date || a.Datetime);
      const dateB = new Date(b.Date || b.Datetime);
      return dateA - dateB; // Ascending order for chart
    });

    // Tambahkan informasi previousClose untuk perhitungan perubahan
    const processedData = sortedData.map((item, index) => ({
      ...item,
      previousClose: index === 0 ? null : sortedData[index - 1].Close
    }));

    // Cari nilai min dan max untuk sumbu Y
    const minValue = Math.min(...processedData.map(item => item.Low));
    const maxValue = Math.max(...processedData.map(item => item.High));

    // Data pertama dan terakhir untuk perhitungan perubahan
    const firstItem = processedData[0] || {};
    const lastItem = processedData[processedData.length - 1] || {};
    const firstClose = firstItem.Close || 0;
    const lastClose = lastItem.Close || 0;
    const change = lastClose - firstClose;
    const percentChange = firstClose ? (change / firstClose) * 100 : 0;

    return {
      isEmpty: false,
      chartData: processedData,
      firstPrice: firstClose,
      lastPrice: lastClose,
      overallChange: change,
      overallPercentChange: percentChange,
      isPositiveOverall: change >= 0,
      lastDate: lastItem.Date || lastItem.Datetime || '',
      yAxisDomain: [
        minValue - (minValue * 0.01), // 1% lebih rendah dari minimum
        maxValue + (maxValue * 0.01)  // 1% lebih tinggi dari maksimum
      ],
      shouldShowAllTicks: processedData.length <= 30
    };
  }, [data]);

  // Jika data kosong, tampilkan pesan
  if (isEmpty) {
    return (
        <div className="chart-container">
          <p>Tidak ada data yang tersedia untuk ditampilkan</p>
        </div>
    );
  }

  // Format ticks pada sumbu X
  const formatXAxis = (tickItem) => {
    const date = new Date(tickItem);
    if (isNaN(date.getTime())) return tickItem;

    // Format singkat (DD/MM) jika banyak data
    if (chartData.length > 30) {
      return date.toLocaleDateString('id-ID', {
        day: '2-digit',
        month: '2-digit'
      });
    }

    // Format lengkap jika sedikit data
    return date.toLocaleDateString('id-ID', {
      day: '2-digit',
      month: '2-digit',
      year: '2-digit'
    });
  };

  // Common chart props for consistent styling
  const commonChartProps = {
    margin: isMobileView ?
        { top: 5, right: 0, left: 0, bottom: 40 } :
        { top: 10, right: 10, left: 5, bottom: 30 }
  };

  // Common axis props
  const xAxisProps = {
    dataKey: "Date",
    tickFormatter: formatXAxis,
    tick: { fontSize: isMobileView ? 9 : 10, fill: '#555' },
    interval: shouldShowAllTicks ? 0 : 'preserveStartEnd',
    angle: -35,
    textAnchor: "end",
    height: 50,
    axisLine: { stroke: '#e0e0e0' },
    tickLine: { stroke: '#e0e0e0' },
    allowDataOverflow: true,
    padding: { left: 5, right: 5 }
  };

  const yAxisProps = {
    domain: yAxisDomain,
    tickFormatter: (value) => formatCurrency(value, currencySymbol),
    tick: { fontSize: isMobileView ? 10 : 11, fill: '#555' },
    width: isMobileView ? 60 : 75,
    axisLine: { stroke: '#e0e0e0' },
    tickLine: { stroke: '#e0e0e0' },
    allowDataOverflow: true,
    padding: { top: 5, bottom: 5 }
  };

  // Common grid props
  const gridProps = {
    strokeDasharray: "2 3",
    stroke: "#f0f0f0",
    vertical: false
  };

  // Common tooltip props
  const tooltipProps = {
    content: <CustomTooltip currencySymbol={currencySymbol} />,
    animationDuration: 0,
    animationEasing: "linear",
    allowEscapeViewBox: { x: true, y: true },
    position: { x: 'auto', y: 'auto' },
    wrapperStyle: { zIndex: 100, maxWidth: '90%' }
  };

  // Common legend props
  const legendProps = {
    verticalAlign: "top",
    height: 20,
    iconSize: isMobileView ? 6 : 8,
    iconType: "circle",
    wrapperStyle: {
      paddingBottom: '2px',
      fontSize: isMobileView ? '9px' : '10px',
      fontWeight: '500'
    },
    align: "right",
    layout: "horizontal",
    margin: { top: 0, right: 0, bottom: 0, left: 0 }
  };

  // Common brush props
  const brushProps = {
    dataKey: "Date",
    height: isMobileView ? 30 : 35,
    stroke: isPositiveOverall ? '#4CAF50' : '#E53935',
    tickFormatter: formatXAxis,
    startIndex: Math.max(0, chartData.length - Math.min(60, chartData.length)),
    fill: "#ffffff",
    travellerWidth: isMobileView ? 8 : 10,
    y: 5,
    padding: { top: 10 },
    className: "custom-brush",
    gap: 5,
    alwaysShowText: false
  };

  // Common reference line props
  const referenceLineProps = {
    y: firstPrice,
    stroke: "#888",
    strokeDasharray: "3 3",
    label: {
      value: `${formatCurrency(firstPrice, currencySymbol)}`,
      position: 'insideBottomLeft',
      fill: '#666',
      fontSize: 9,
      fontWeight: '500',
      offset: 5
    }
  };

  // Render the chart based on chartType with all animations disabled
  const renderChart = () => {
    switch(chartType) {
      case 'line':
        return (
            <LineChart data={chartData} {...commonChartProps}>
              <CartesianGrid {...gridProps} />
              <XAxis {...xAxisProps} />
              <YAxis {...yAxisProps} />
              <Tooltip {...tooltipProps} />
              <Legend {...legendProps} />

              <Line
                  type="monotone"
                  dataKey="Close"
                  name="Harga Penutupan"
                  stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                  strokeWidth={2}
                  dot={chartData.length > 60 ? false : { r: 2, fill: isPositiveOverall ? '#4CAF50' : '#E53935', strokeWidth: 1, stroke: 'white' }}
                  activeDot={{
                    r: 6,
                    fill: isPositiveOverall ? '#4CAF50' : '#E53935',
                    stroke: 'white',
                    strokeWidth: 2
                  }}
                  isAnimationActive={false} // Hilangkan animasi
                  animationDuration={0}
                  animationEasing="linear"
              />

              <ReferenceLine {...referenceLineProps} />
              <Brush {...brushProps} />
            </LineChart>
        );

      case 'area':
        return (
            <AreaChart data={chartData} {...commonChartProps}>
              <defs>
                <linearGradient id="colorClose" x1="0" y1="0" x2="0" y2="1">
                  <stop
                      offset="5%"
                      stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'}
                      stopOpacity={0.25}
                  />
                  <stop
                      offset="95%"
                      stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'}
                      stopOpacity={0}
                  />
                </linearGradient>
              </defs>
              <CartesianGrid {...gridProps} />
              <XAxis {...xAxisProps} />
              <YAxis {...yAxisProps} />
              <Tooltip {...tooltipProps} />
              <Legend {...legendProps} />

              <Area
                  type="monotone"
                  dataKey="Close"
                  name="Area Harga"
                  fill="url(#colorClose)"
                  stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                  strokeWidth={1.5}
                  isAnimationActive={false} // Hilangkan animasi
                  animationDuration={0}
                  animationEasing="linear"
                  dot={false}
                  activeDot={{
                    r: 5,
                    fill: isPositiveOverall ? '#4CAF50' : '#E53935',
                    stroke: 'white',
                    strokeWidth: 1.5
                  }}
              />

              <ReferenceLine {...referenceLineProps} />
              <Brush {...brushProps} />
            </AreaChart>
        );

      default: // composed chart
        return (
            <ComposedChart data={chartData} {...commonChartProps}>
              <defs>
                <linearGradient id="colorClose" x1="0" y1="0" x2="0" y2="1">
                  <stop
                      offset="5%"
                      stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'}
                      stopOpacity={0.25}
                  />
                  <stop
                      offset="95%"
                      stopColor={isPositiveOverall ? '#4CAF50' : '#E53935'}
                      stopOpacity={0}
                  />
                </linearGradient>
              </defs>
              <CartesianGrid {...gridProps} />
              <XAxis {...xAxisProps} />
              <YAxis {...yAxisProps} />
              <Tooltip {...tooltipProps} />
              <Legend {...legendProps} />

              <Area
                  type="monotone"
                  dataKey="Close"
                  name="Area Harga"
                  fill="url(#colorClose)"
                  stroke="none"
                  fillOpacity={0.2}
                  isAnimationActive={false} // Hilangkan animasi
                  animationDuration={0}
              />

              <Line
                  type="monotone"
                  dataKey="Close"
                  name="Harga Penutupan"
                  stroke={isPositiveOverall ? '#4CAF50' : '#E53935'}
                  strokeWidth={2.5}
                  dot={chartData.length > 60 ? false : { r: 2, fill: isPositiveOverall ? '#4CAF50' : '#E53935', strokeWidth: 1, stroke: 'white' }}
                  activeDot={{
                    r: 7,
                    fill: isPositiveOverall ? '#4CAF50' : '#E53935',
                    stroke: 'white',
                    strokeWidth: 2
                  }}
                  isAnimationActive={false} // Hilangkan animasi
                  animationDuration={0}
                  animationEasing="linear"
              />

              <ReferenceLine {...referenceLineProps} />
              <Brush {...brushProps} />
            </ComposedChart>
        );
    }
  };

  return (
      <div className="chart-container" style={{
        padding: '10px',
        backgroundColor: '#fff',
        borderRadius: '16px',
        boxShadow: '0 2px 15px rgba(0,0,0,0.05)',
        transition: 'none' // Hilangkan transisi
      }}>
        {/* Panel harga terakhir */}
        <div style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '15px',
          borderRadius: '12px',
          position: 'relative',
          margin: '0 0 15px 0',
          boxShadow: '0 2px 10px rgba(0,0,0,0.03)',
          backgroundColor: isPositiveOverall ? 'rgba(76, 175, 80, 0.03)' : 'rgba(229, 57, 53, 0.03)',
          transition: 'none' // Hilangkan transisi
        }}>
          <div style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '5px',
            height: '100%',
            backgroundColor: isPositiveOverall ? '#4CAF50' : '#E53935',
            opacity: 0.8,
            borderTopLeftRadius: '12px',
            borderBottomLeftRadius: '12px'
          }}></div>
          <div>
            <div style={{
              fontSize: '14px',
              color: '#666',
              marginBottom: '6px',
              fontWeight: '500',
              display: 'flex',
              alignItems: 'center'
            }}>
            <span style={{
              display: 'inline-block',
              width: '8px',
              height: '8px',
              borderRadius: '50%',
              backgroundColor: isPositiveOverall ? '#4CAF50' : '#E53935',
              marginRight: '8px'
            }}></span>
              {formatDate(lastDate)} - Harga Terakhir
            </div>
            <div style={{
              fontSize: '28px',
              fontWeight: 'bold',
              color: isPositiveOverall ? '#2E7D32' : '#C62828',
              letterSpacing: '-0.5px'
            }}>
              {formatCurrency(lastPrice, currencySymbol)}
            </div>
          </div>
          <div style={{
            textAlign: 'right',
            backgroundColor: isPositiveOverall ? 'rgba(76, 175, 80, 0.1)' : 'rgba(229, 57, 53, 0.1)',
            padding: '12px 16px',
            borderRadius: '8px'
          }}>
            <div style={{
              fontSize: '14px',
              color: '#666',
              marginBottom: '6px',
              fontWeight: '500'
            }}>
              Perubahan
            </div>
            <div style={{
              fontSize: '22px',
              fontWeight: 'bold',
              color: isPositiveOverall ? '#2E7D32' : '#C62828',
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'flex-end'
            }}>
              <div>
                {isPositiveOverall ? '+' : ''}{formatCurrency(overallChange, currencySymbol)}
              </div>
              <div style={{
                fontSize: '16px',
                backgroundColor: isPositiveOverall ? 'rgba(76, 175, 80, 0.2)' : 'rgba(229, 57, 53, 0.2)',
                padding: '3px 8px',
                borderRadius: '4px',
                marginTop: '4px'
              }}>
                {isPositiveOverall ? '+' : ''}{overallPercentChange.toFixed(2)}%
              </div>
            </div>
          </div>
        </div>

        {/* Improved chart-wrapper */}
        <div className="chart-wrapper" style={{
          position: 'relative',
          backgroundColor: 'white',
          borderRadius: '12px',
          padding: '10px 10px 10px 5px',
          boxShadow: '0 4px 12px rgba(0,0,0,0.08)',
          border: `1px solid ${isPositiveOverall ? 'rgba(76, 175, 80, 0.2)' : 'rgba(229, 57, 53, 0.2)'}`,
          transition: 'none',
          marginTop: '20px',
          overflow: 'visible', // Changed from 'hidden' to 'visible' to allow chart to display fully
          background: 'white',
          width: '100%'
        }}>
          <div style={{
            fontSize: '14px',
            fontWeight: '600',
            marginBottom: '5px',
            color: '#333',
            paddingBottom: '5px',
            display: 'flex',
            justifyContent: 'flex-end',
            alignItems: 'center',
            padding: '0 10px'
          }}>
            <div style={{
              fontSize: '12px',
              backgroundColor: isPositiveOverall ? 'rgba(76, 175, 80, 0.1)' : 'rgba(229, 57, 53, 0.1)',
              padding: '2px 8px',
              borderRadius: '12px',
              color: isPositiveOverall ? '#2E7D32' : '#C62828',
              fontWeight: '500'
            }}>
              {chartData.length} data
            </div>
          </div>
          {/* Watermark */}
          <div style={{
            position: 'absolute',
            right: '10px',
            top: '40px',
            fontSize: '10px',
            color: 'rgba(0,0,0,0.08)',
            fontWeight: '600',
            zIndex: 0,
            pointerEvents: 'none',
            fontStyle: 'italic',
            transform: 'rotate(-5deg)'
          }}>
            Stock Viewer
          </div>

          <div style={{ width: '100%', height: isMobileView ? '400px' : '500px' }}>
            <ResponsiveContainer width="100%" height="100%" debounce={0}>
              {renderChart()}
            </ResponsiveContainer>
          </div>
        </div>
      </div>
  );
};

export default StockChart;
